local.file "mimir_client_id" {
  filename = "/var/run/secrets/mimir-oauth/clientId"
}
local.file "alertmanager_global" {
  filename = "/etc/alloy/alertmanager-global/config"
}
mimir.rules.kubernetes "mimir" {
  address       = "https://mimir.cloud.witl.xyz"
  sync_interval = "2m"
  oauth2 {
    token_url           = "https://sso-3da0e7d4.sso.duosecurity.com/oauth/DIV21P82KMG9NOTNQW6J/token"
    client_id           = string.trim_space(local.file.mimir_client_id.content)
    client_secret_file  = "/var/run/secrets/mimir-oauth/clientSecret"
    scopes              = ["mimir:write", "mimir:read"]
    endpoint_params     = { "grant_type" = "client_credentials" }
  }
}
mimir.alerts.kubernetes "mimir" {
  address       = "https://mimir.cloud.witl.xyz"
  global_config = local.file.alertmanager_global.content
  sync_interval = "2m"
  oauth2 {
    token_url           = "https://sso-3da0e7d4.sso.duosecurity.com/oauth/DIV21P82KMG9NOTNQW6J/token"
    client_id           = string.trim_space(local.file.mimir_client_id.content)
    client_secret_file  = "/var/run/secrets/mimir-oauth/clientSecret"
    scopes              = ["mimir:write", "mimir:read"]
    endpoint_params     = { "grant_type" = "client_credentials" }
  }
}

